const sectionAnchors: Record<string, string> = {
  ...controlledSections,
  "Attention Mode": "attention_mode",
  "Input Boundary Model Options": "input_layer_weight_option",
  "Layer Stack Options": "stack_num_layers",
  "Layer Stack Submodule Options": "submodule_stack_residual_model_flag",
  "Mixture Of Experts Model Options": "mixture_of_experts_model",
  "Output Boundary Model Options": "output_layer_weight_option",
};

export function configFieldSectionFixture(path: string[]) {
  return {
    sectionIdPath: path.map((title) => sectionAnchors[title] ?? title.toLowerCase().replace(/[^a-z0-9]+/g, "_")),
    sectionControlFieldKey: controlledSections[path[path.length - 1]!] ?? null,
    hasFlatControls: false,
  };
}
